DROP POLICY "Published website photos only" ON storage.objects;
CREATE POLICY "Published website photos only" ON storage.objects FOR SELECT TO anon USING (bucket_id = 'website-photos' AND (EXISTS (SELECT 1 FROM public.website_content c WHERE c.value = '/api/public/website-photo?path=' || storage.objects.name) OR EXISTS (SELECT 1 FROM public.events e WHERE e.image_url = '/api/public/website-photo?path=' || storage.objects.name) OR EXISTS (SELECT 1 FROM public.announcements a WHERE a.image_url = '/api/public/website-photo?path=' || storage.objects.name)));
CREATE OR REPLACE FUNCTION public.validate_content_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v jsonb; BEGIN v=to_jsonb(NEW); IF v ? 'title' AND length(trim(v->>'title'))=0 THEN RAISE EXCEPTION 'Title is required'; END IF; IF v ? 'name' AND length(trim(v->>'name'))=0 THEN RAISE EXCEPTION 'Name is required'; END IF; IF v ? 'message' AND length(trim(v->>'message'))=0 THEN RAISE EXCEPTION 'Message is required'; END IF; IF v->>'start_date' IS NOT NULL AND v->>'end_date' IS NOT NULL AND (v->>'end_date')::date<(v->>'start_date')::date THEN RAISE EXCEPTION 'End date must be on or after start date'; END IF; IF v->>'starts_on' IS NOT NULL AND v->>'ends_on' IS NOT NULL AND (v->>'ends_on')::date<(v->>'starts_on')::date THEN RAISE EXCEPTION 'End date must be on or after start date'; END IF; IF v ? 'price' AND v->>'price' !~ '^\$?[0-9]+(\.[0-9]{1,2})?$' THEN RAISE EXCEPTION 'Enter a valid dollar amount'; END IF; IF coalesce(v->>'image_url','')<>'' AND v->>'image_url' !~ '^https://' AND v->>'image_url' !~ '^/api/public/website-photo\?path=[0-9a-f-]{36}/[0-9a-f-]{36}\.jpg$' THEN RAISE EXCEPTION 'Choose a website photo or use a secure image link'; END IF; RETURN NEW; END $$;